    case '?': { static const uint8_t g[5] = {6, 1, 2, 0, 2}; return g[row]; }
    case '0': { static const uint8_t g[5] = {7, 5, 5, 5, 7}; return g[row]; }
    case '1': { static const uint8_t g[5] = {2, 6, 2, 2, 7}; return g[row]; }
